  var ops=RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,level.registryAccess());var meta=RealisticGenerator.CODEC.codec().encodeStart(ops,generator).getOrThrow().getAsJsonObject();require(meta.get("shape_version").getAsInt()==BorealCrownSchema.schema(PyramidGallerySchema.schema((generator.reimaginedDefinition()==5?160+2*generator.mansionWingDefinition()+generator.overworldDefinition():generator.reimaginedDefinition()==4?130+2*generator.mansionWingDefinition()+generator.overworldDefinition():generator.reimaginedDefinition()==3?118+2*generator.mansionWingDefinition()+generator.overworldDefinition():generator.mansionWingDefinition()==1?106+2*(generator.reimaginedDefinition()-1)+generator.overworldDefinition():generator.reimaginedDefinition()==2?104+generator.overworldDefinition():102+generator.overworldDefinition()),generator.pyramidGalleryDefinition()),generator.borealCrownDefinition())&&meta.has("reimagined_layouts"),"Private early102 plus explicit layout definition");
